def main() -> None:
    source = SOURCE.read_text(encoding="utf-8")
    marker = "const DATA: AuditData = "
    begin = source.index(marker) + len(marker)
    end = source.index("// END INLINE AUDIT DATA", begin)
    audit = json.loads(source[begin:end].strip().rstrip(";"))
    percentages = json.loads(PERCENTAGES.read_text(encoding="utf-8-sig"))
    ids = {item["id"] for item in percentages["systems"]}
    if len(ids) != 36 or not ids.issubset({item["id"] for item in audit["systems"]}):
        raise SystemExit("百分比系统数或对应 ID 与原面板不匹配，停止导出。")
    now = dt.datetime.now(dt.timezone(dt.timedelta(hours=8))).isoformat(timespec="seconds")
    payload = json.dumps({"audit": audit, "percent": percentages}, ensure_ascii=False, separators=(",", ":"))
    payload = payload.replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
    page = PAGE.replace("{{DATA}}", payload).replace("{{NOW}}", html.escape(now))
    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    OUTPUT.write_bytes(page.encode("utf-8"))
    print(json.dumps({"output": str(OUTPUT), "bytes": OUTPUT.stat().st_size, "systems": len(ids), "structures": len(audit["structures"]), "source_records": len(audit["files"]), "generated_at": now}, ensure_ascii=False))


if __name__ == "__main__":
    main()
